public class StdDateFormat_isLenient_TriageGen0Test {

    @Test
    public void testIsLenient_DefaultNullCase() {
        // The default constructor initializes _lenient to null
        // According to the code: if (_lenient == null) return false;
        StdDateFormat df = new StdDateFormat();
        assertFalse("When _lenient is null, isLenient() should return false", df.isLenient());
    }







    /**
     * Helper method to instantiate StdDateFormat using the protected constructor via reflection.
     */
    private StdDateFormat createWithLenient(TimeZone tz, Locale loc, Boolean lenient) {
        try {
            Constructor<StdDateFormat> constructor = StdDateFormat.class.getDeclaredConstructor(
                    TimeZone.class, Locale.class, Boolean.class);
            constructor.setAccessible(true);
            return constructor.newInstance(tz, loc, lenient);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}

