public class StdDateFormat_isLenient_TriageGen0Test {







    @Test
    public void testIsLenient_AfterSetLenient() {
        // Test using the public setter provided in the class
        StdDateFormat df = new StdDateFormat();

        // Initially null -> false
        assertFalse(df.isLenient());

        // Set to true
        df.setLenient(true);
        assertTrue(df.isLenient());

        // Set to false
        df.setLenient(false);
        assertFalse(df.isLenient());
    }

    /**
